<template>
  <div
    class="fu-split-button"
    :class="[sizeClass, variantClass]"
    :style="splitButtonStyle"
    ref="splitButtonRef"
    @keydown="onKeydown"
  >
    <!-- Main button: runs the main action, does not open the menu -->
    <button
      class="fu-split-button__main"
      :disabled="disabled"
      @click="mainAction"
      type="button"
    >
      <component v-if="icon" :is="icon" class="fu-split-button__icon" />
      <slot name="main" :open="isOpen">
        <span class="fu-split-button__label"><slot /></span>
      </slot>
      <slot name="badge" />
    </button>

    <!-- Toggle: opens the menu -->
    <button
      ref="toggleRef"
      class="fu-split-button__toggle"
      @click="toggleDropdown"
      aria-haspopup="menu"
      :aria-expanded="isOpen"
      :aria-controls="isOpen ? menuId : undefined"
      :aria-label="ariaLabel"
      :disabled="disabled"
      type="button"
    >
      <ChevronDown />
    </button>

    <!-- Teleported menu -->
    <teleport to="body">
      <transition name="fade">
        <div
          v-if="isOpen"
          :id="menuId"
          ref="dropdownRef"
          class="fu-split-button__dropdown"
          role="menu"
          :aria-label="ariaLabel"
          :style="menuStyle"
          @keydown="onKeydown"
        >
          <template v-for="(group, gIndex) in menuGroups" :key="gIndex">
            <!-- Divider between groups -->
            <div
              v-if="gIndex > 0"
              class="fu-split-button__divider"
              role="separator"
            />

            <div
              role="group"
              :aria-labelledby="group.label ? `${menuId}-g${gIndex}` : undefined"
            >
              <div
                v-if="group.label"
                :id="`${menuId}-g${gIndex}`"
                class="fu-split-button__group-label"
              >
                {{ group.label }}
              </div>

              <button
                v-for="entry in group.entries"
                :key="entry.key"
                :ref="(el) => (itemRefs[entry.index] = el as HTMLElement | null)"
                type="button"
                class="fu-split-button__option"
                :class="{
                  'fu-split-button__option--selected': entry.item.selected,
                  'fu-split-button__option--disabled': entry.item.disabled,
                }"
                :role="entry.item.selected !== undefined ? 'menuitemradio' : 'menuitem'"
                :aria-checked="entry.item.selected !== undefined ? !!entry.item.selected : undefined"
                :aria-disabled="entry.item.disabled || undefined"
                tabindex="-1"
                @click="selectOption(entry.item)"
              >
                <img
                  v-if="entry.item.type === 'image' && entry.item.imageUrl"
                  :src="entry.item.imageUrl"
                  class="fu-split-button__option-image"
                  alt=""
                />
                <component
                  v-else-if="entry.item.icon"
                  :is="entry.item.icon"
                  class="fu-split-button__option-icon"
                  aria-hidden="true"
                />
                <span class="fu-split-button__option-text">
                  <span class="fu-split-button__option-label">{{ entry.item.label }}</span>
                  <small
                    v-if="entry.item.description"
                    class="fu-split-button__option-description"
                  >
                    {{ entry.item.description }}
                  </small>
                </span>
                <Check
                  v-if="entry.item.selected"
                  class="fu-split-button__option-check"
                  aria-hidden="true"
                />
              </button>
            </div>
          </template>
        </div>
      </transition>
    </teleport>
  </div>
</template>

<script lang="ts">
import type { Component } from "vue";

/** One item in the split button's menu. */
export interface SplitButtonItem {
  label: string;
  /** Emitted with `select`. */
  value?: string | number;
  /** A Lucide (or any) icon component. */
  icon?: Component | any;
  /** Legacy: `"image"` shows `imageUrl` as an avatar. `"icon"` is no longer needed. */
  type?: "icon" | "image";
  imageUrl?: string;
  /** Muted second line under the label. */
  description?: string;
  /** Shows a check mark. Setting it (true or false) makes the item a `menuitemradio`. */
  selected?: boolean;
  disabled?: boolean;
  onClick?: () => void;
}

/** A labelled section of the menu. Leave `label` out for a section with no heading. */
export interface SplitButtonGroup {
  label?: string;
  actions: SplitButtonItem[];
}
</script>

<script setup lang="ts">
import { ref, computed, nextTick, onBeforeUnmount } from "vue";
import { ChevronDown, Check } from "@lucide/vue";

const props = withDefaults(
  defineProps<{
    /** Flat list of options. Ignored when `groups` is given. */
    options?: SplitButtonItem[];
    /** Labelled sections with dividers between them. Used instead of `options`. */
    groups?: SplitButtonGroup[];
    disabled?: boolean;
    size?: "sm" | "md" | "lg";
    variant?: "solid" | "subtle" | "outline" | "ghost" | "danger";
    color?: string;
    icon?: any;
    align?: "left" | "center" | "right";
    buttonWidth?: string;
    /** Accessible name for the toggle and the menu. */
    ariaLabel?: string;
  }>(),
  {
    options: () => [],
    groups: undefined,
    size: "sm",
    variant: "solid",
    align: "right",
    ariaLabel: "Toggle dropdown",
  }
);

const emit = defineEmits<{
  (e: "main-action"): void;
  (e: "select", option: SplitButtonItem): void;
}>();

defineSlots<{
  /** Main button label. */
  default?(): any;
  /** Replaces the whole main button content (label + badge). */
  main?(props: { open: boolean }): any;
  /** Small badge or dot shown after the label, e.g. "unsaved changes". */
  badge?(): any;
}>();

const isOpen = ref(false);
const dropdownRef = ref<HTMLElement | null>(null);
const splitButtonRef = ref<HTMLElement | null>(null);
const toggleRef = ref<HTMLElement | null>(null);
const itemRefs = ref<(HTMLElement | null)[]>([]);
const menuStyle = ref<Record<string, string>>({});
const menuId = `fu-split-button-${Math.random().toString(36).slice(2, 9)}`;

const sizeClass = computed(() => `fu-split-button--${props.size}`);
const variantClass = computed(() => `fu-split-button--${props.variant}`);

const splitButtonStyle = computed(() => ({
  ...(props.color ? { "--fu-split-bg": props.color } : {}),
  ...(props.buttonWidth ? { width: props.buttonWidth } : {}),
}));

/* ---------- Items ---------- */

// `options` is treated as one group with no heading, so both props share one render path.
const sourceGroups = computed<SplitButtonGroup[]>(() =>
  props.groups?.length ? props.groups : [{ actions: props.options ?? [] }]
);

// Each item gets a flat index so the arrow keys can move across groups.
const menuGroups = computed(() => {
  let index = 0;
  return sourceGroups.value
    .filter((g) => g.actions?.length)
    .map((group, gIndex) => ({
      label: group.label,
      entries: group.actions.map((item, i) => ({
        item,
        index: index++,
        key: `${gIndex}-${i}-${item.value ?? item.label}`,
      })),
    }));
});

const flatItems = computed(() => menuGroups.value.flatMap((g) => g.entries.map((e) => e.item)));

/* ---------- Open / close ---------- */

function toggleDropdown() {
  if (props.disabled) return;
  isOpen.value ? closeMenu() : openMenu();
}

async function openMenu(focus: "first" | "last" | "selected" = "selected") {
  if (props.disabled || isOpen.value) return;
  itemRefs.value = [];
  isOpen.value = true;
  await nextTick();
  positionDropdown();
  window.addEventListener("click", onClickOutside);
  window.addEventListener("resize", positionDropdown);
  window.addEventListener("scroll", positionDropdown, true);

  const items = flatItems.value;
  let index = -1;
  if (focus === "selected") index = items.findIndex((i) => i.selected && !i.disabled);
  if (index === -1) index = firstEnabled(focus === "last" ? -1 : 1);
  itemRefs.value[index]?.focus();
}

function closeMenu({ focusToggle = false } = {}) {
  if (!isOpen.value) return;
  isOpen.value = false;
  removeListeners();
  if (focusToggle) toggleRef.value?.focus();
}

function removeListeners() {
  window.removeEventListener("click", onClickOutside);
  window.removeEventListener("resize", positionDropdown);
  window.removeEventListener("scroll", positionDropdown, true);
}

function onClickOutside(e: MouseEvent) {
  if (
    splitButtonRef.value?.contains(e.target as Node) ||
    dropdownRef.value?.contains(e.target as Node)
  )
    return;
  closeMenu();
}

/* ---------- Position ---------- */

// Opens below by default; flips above when there isn't room. If neither side fits,
// it uses the bigger side and scrolls inside the menu.
function positionDropdown(event?: Event) {
  if (!splitButtonRef.value || !dropdownRef.value) return;
  // Scrolling inside the menu itself doesn't move the button.
  if (event?.type === "scroll" && dropdownRef.value.contains(event.target as Node)) return;

  const rect = splitButtonRef.value.getBoundingClientRect();
  const menu = dropdownRef.value;
  const gap = 4;
  const edge = 8;

  const menuWidth = menu.offsetWidth;
  // Full content height, even when max-height is already limiting it (+ borders).
  const menuHeight = menu.scrollHeight + (menu.offsetHeight - menu.clientHeight);

  const spaceBelow = window.innerHeight - rect.bottom - gap - edge;
  const spaceAbove = rect.top - gap - edge;
  const openUp = menuHeight > spaceBelow && spaceAbove > spaceBelow;
  const available = openUp ? spaceAbove : spaceBelow;
  const height = Math.min(menuHeight, available);

  const top = openUp ? rect.top - gap - height : rect.bottom + gap;

  let left = rect.left;
  if (props.align === "right") left = rect.right - menuWidth;
  else if (props.align === "center") left = rect.left + rect.width / 2 - menuWidth / 2;
  left = Math.max(edge, Math.min(left, window.innerWidth - menuWidth - edge));

  menuStyle.value = {
    position: "absolute",
    top: `${top + window.scrollY}px`,
    left: `${left + window.scrollX}px`,
    zIndex: "1000",
    ...(menuHeight > available ? { maxHeight: `${available}px` } : {}),
  };
}

/* ---------- Actions ---------- */

function mainAction() {
  if (!props.disabled) emit("main-action");
}

function selectOption(option: SplitButtonItem) {
  if (option.disabled) return;
  option.onClick?.();
  emit("select", option);
  closeMenu({ focusToggle: true });
}

/* ---------- Keyboard ---------- */

function firstEnabled(direction: 1 | -1) {
  const items = flatItems.value;
  const n = items.length;
  for (let step = 0; step < n; step++) {
    const i = direction === 1 ? step : n - 1 - step;
    if (!items[i].disabled) return i;
  }
  return -1;
}

function moveFocus(delta: 1 | -1) {
  const items = flatItems.value;
  const n = items.length;
  if (!n) return;
  let i = itemRefs.value.findIndex((el) => el === document.activeElement);
  if (i === -1) i = delta === 1 ? -1 : n;
  for (let step = 0; step < n; step++) {
    i = (i + delta + n) % n;
    if (!items[i]?.disabled) break;
  }
  itemRefs.value[i]?.focus();
}

function onKeydown(event: KeyboardEvent) {
  if (!isOpen.value) {
    if (event.target === toggleRef.value && ["ArrowDown", "ArrowUp"].includes(event.key)) {
      event.preventDefault();
      openMenu(event.key === "ArrowUp" ? "last" : "first");
    }
    return;
  }

  switch (event.key) {
    case "Escape":
      event.preventDefault();
      event.stopPropagation();
      closeMenu({ focusToggle: true });
      break;
    case "ArrowDown":
      event.preventDefault();
      moveFocus(1);
      break;
    case "ArrowUp":
      event.preventDefault();
      moveFocus(-1);
      break;
    case "Home":
      event.preventDefault();
      itemRefs.value[firstEnabled(1)]?.focus();
      break;
    case "End":
      event.preventDefault();
      itemRefs.value[firstEnabled(-1)]?.focus();
      break;
    case "Tab":
      // The menu is teleported, so Tab would jump to the end of the page. Close and stay put.
      if (dropdownRef.value?.contains(event.target as Node)) {
        event.preventDefault();
        closeMenu({ focusToggle: true });
      } else {
        closeMenu();
      }
      break;
  }
}

onBeforeUnmount(removeListeners);

defineExpose({ open: openMenu, close: closeMenu });
</script>

