<script setup lang="ts">
/**
 * FusionPickerPopover
 * A wide popover with a list on the left and a preview on the right. Pointing at an item shows what it is
 * (a picture, a title and a short description), and a button under it acts on that item, for example
 * "Add to navigation". Put any trigger in the `trigger` slot.
 */
import { computed, ref, watch, type Component } from "vue";
import FuPopover from "../popover/FuPopover.vue";
import FusionButton from "../button/FusionButton.vue";

export interface PickerItem {
    key: string | number;
    /** The row in the list. */
    label: string;
    icon?: Component;
    /** Bigger heading in the preview. Defaults to `label`. */
    title?: string;
    /** A line or two under the heading in the preview. */
    description?: string;
    /** Picture for the preview. Without one, the item's icon is shown large on a soft panel. */
    image?: string;
    disabled?: boolean;
}

const props = withDefaults(
    defineProps<{
        items: PickerItem[];
        /** Small heading above the list, for example "Views". */
        heading?: string;
        /** Label of the button in the preview. */
        actionLabel?: string;
        /** Width of the whole popover. */
        width?: string;
        /** A fixed height, so the popover never changes size as the preview changes. The list and preview scroll inside it. */
        height?: string;
        align?: "left" | "right" | "center";
        /** Close the popover after the button is pressed. */
        closeOnAction?: boolean;
        emptyText?: string;
    }>(),
    {
        heading: "",
        actionLabel: "Add",
        width: "46rem",
        height: "21rem",
        align: "left",
        closeOnAction: true,
        emptyText: "Nothing left to add.",
    },
);

const emit = defineEmits<{
    /** The button in the preview was pressed for this item. */
    (e: "action", item: PickerItem): void;
    /** A different item was picked in the list. */
    (e: "select", item: PickerItem): void;
}>();

const popover = ref<InstanceType<typeof FuPopover> | null>(null);
const selectedKey = ref<string | number | null>(null);

const selected = computed(() => props.items.find((i) => i.key === selectedKey.value) ?? props.items[0] ?? null);

// The first item is shown until you pick another; the pick resets when the list changes
watch(
    () => props.items.map((i) => i.key).join("|"),
    () => {
        if (!props.items.some((i) => i.key === selectedKey.value)) selectedKey.value = props.items[0]?.key ?? null;
    },
    { immediate: true },
);

function pick(item: PickerItem) {
    if (item.disabled) return;
    selectedKey.value = item.key;
    emit("select", item);
}

/** Up and down move through the list, like a listbox. */
function onKeydown(e: KeyboardEvent) {
    if (e.key !== "ArrowDown" && e.key !== "ArrowUp") return;
    e.preventDefault();
    const list = props.items.filter((i) => !i.disabled);
    const at = list.findIndex((i) => i.key === selected.value?.key);
    const next = list[Math.max(0, Math.min(list.length - 1, at + (e.key === "ArrowDown" ? 1 : -1)))];
    if (next) pick(next);
}

function act() {
    if (!selected.value || selected.value.disabled) return;
    emit("action", selected.value);
    if (props.closeOnAction) popover.value?.close();
}
</script>

<template>
    <FuPopover ref="popover" :width="width" :maxHeight="height" :align="align">
        <template #trigger><slot name="trigger" /></template>

        <div v-if="items.length" class="fu-picker" :style="{ height }">
            <!-- The list -->
            <div class="fu-picker__list customScrollBar" role="listbox" :aria-label="heading || 'Choose'" tabindex="0" @keydown="onKeydown">
                <div v-if="heading" class="fu-picker__heading">{{ heading }}</div>
                <button
                    v-for="item in items"
                    :key="item.key"
                    type="button"
                    role="option"
                    class="fu-picker__item"
                    :class="{ 'is-selected': selected?.key === item.key }"
                    :aria-selected="selected?.key === item.key"
                    :disabled="item.disabled"
                    @click="pick(item)"
                    @mouseenter="pick(item)"
                >
                    <component :is="item.icon" v-if="item.icon" :size="18" class="fu-picker__icon" />
                    <span class="fu-picker__label">{{ item.label }}</span>
                </button>
            </div>

            <!-- The preview of the picked item -->
            <div v-if="selected" class="fu-picker__preview">
                <slot name="preview" :item="selected">
                    <div class="fu-picker__picture">
                        <img v-if="selected.image" :src="selected.image" :alt="selected.title || selected.label" />
                        <component :is="selected.icon" v-else-if="selected.icon" :size="44" :stroke-width="1.5" />
                    </div>
                </slot>
                <h4 class="fu-picker__title">{{ selected.title || selected.label }}</h4>
                <p v-if="selected.description" class="fu-picker__desc">{{ selected.description }}</p>
                <FusionButton :text="actionLabel" variant="solid" size="sm" :disabled="selected.disabled" @click="act" />
            </div>
        </div>

        <p v-else class="fu-picker__empty">{{ emptyText }}</p>
    </FuPopover>
</template>

