<template>
  <FuCard :href="href" :clickable="clickable" class="fu-project-card" @click="$emit('click', $event)">
    <span class="fu-project-card__name">{{ name }}</span>

    <span v-if="stage || highlight" class="fu-project-card__status">
      <template v-if="stage">{{ stage }}</template>
      <template v-if="stage && highlight"> · </template>
      <strong v-if="highlight" class="fu-project-card__highlight">{{ highlight }}</strong>
    </span>

    <span v-if="meta" class="fu-project-card__meta">{{ meta }}</span>
  </FuCard>
</template>

<script setup lang="ts">
import FuCard from "./FuCard.vue";

export interface FuProjectCardProps {
  /** Project name */
  name: string;
  /** Current stage, e.g. "Design stage" */
  stage?: string;
  /** What is needed next, shown in the accent colour, e.g. "we need your feedback" */
  highlight?: string;
  /** Small footer line, e.g. "Step 2 of 4" */
  meta?: string;
  href?: string;
  clickable?: boolean;
}

withDefaults(defineProps<FuProjectCardProps>(), { clickable: false });
defineEmits<{ (e: "click", ev: MouseEvent): void }>();
</script>

