<script setup lang="ts">
/**
 * FusionBarChart
 * Bars for one or several series, vertical or horizontal, grouped or stacked.
 */
import { computed, ref } from "vue";

export interface BarSeries {
    name: string;
    values: number[];
    /** Any CSS colour. Defaults to the next colour in the palette. */
    color?: string;
}

const PALETTE = [
    "var(--fu-brand-primary-base, #2a0808)",
    "#3a8be0",
    "var(--fu-color-success, #6c9a2e)",
    "var(--fu-color-warning, #f0a135)",
    "var(--fu-color-danger, #c2417a)",
];

const props = withDefaults(
    defineProps<{
        categories: string[];
        series: BarSeries[];
        orientation?: "vertical" | "horizontal";
        stacked?: boolean;
        /** Plot height in px (vertical only). */
        height?: number;
        /** Top of the scale. By default it rounds the biggest value up to a tidy number. */
        max?: number;
        showValues?: boolean;
        showGrid?: boolean;
        legend?: boolean;
        formatValue?: (n: number) => string;
        loading?: boolean;
        emptyText?: string;
    }>(),
    {
        orientation: "vertical",
        stacked: false,
        height: 240,
        showValues: false,
        showGrid: true,
        legend: true,
        loading: false,
        emptyText: "No data",
    },
);

const emit = defineEmits<{ (e: "select", payload: { category: string; series: string; value: number }): void }>();

const active = ref<string | null>(null);
const fmt = (n: number) => (props.formatValue ? props.formatValue(n) : String(Math.round(n * 100) / 100));

const coloured = computed(() => props.series.map((s, i) => ({ ...s, color: s.color ?? PALETTE[i % PALETTE.length] })));

const rawMax = computed(() => {
    if (props.stacked) {
        return Math.max(0, ...props.categories.map((_, ci) => props.series.reduce((a, s) => a + (s.values[ci] || 0), 0)));
    }
    return Math.max(0, ...props.series.flatMap((s) => s.values));
});

/** Round up to 1, 2, 2.5, 5 or 10 times a power of ten. */
const niceMax = computed(() => {
    if (props.max !== undefined) return props.max;
    const v = rawMax.value || 1;
    const pow = Math.pow(10, Math.floor(Math.log10(v)));
    const step = [1, 2, 2.5, 5, 10].find((m) => m * pow >= v) ?? 10;
    return step * pow;
});

const ticks = computed(() => [0, 1, 2, 3, 4].map((i) => (niceMax.value / 4) * i));
const hasData = computed(() => rawMax.value > 0);
const pctOf = (n: number) => `${Math.min(100, (n / niceMax.value) * 100)}%`;

function bars(ci: number) {
    return coloured.value.map((s) => ({ name: s.name, color: s.color, value: s.values[ci] || 0 }));
}
</script>

<template>
    <figure class="fu-bars" :class="`fu-bars--${orientation}`">
        <div v-if="loading" class="fu-bars__loading" :style="{ height: `${height}px` }" />
        <p v-else-if="!hasData" class="fu-bars__empty" :style="{ minHeight: `${height}px` }">{{ emptyText }}</p>

        <!-- VERTICAL -->
        <div v-else-if="orientation === 'vertical'" class="fu-bars__v">
            <div class="fu-bars__yaxis" :style="{ height: `${height}px` }">
                <span v-for="t in [...ticks].reverse()" :key="t">{{ fmt(t) }}</span>
            </div>
            <div class="fu-bars__plotwrap">
                <div class="fu-bars__plot" :style="{ height: `${height}px` }">
                    <div v-if="showGrid" class="fu-bars__grid" aria-hidden="true">
                        <span v-for="t in ticks" :key="t" :style="{ bottom: pctOf(t) }" />
                    </div>
                    <div v-for="(c, ci) in categories" :key="c" class="fu-bars__group" :class="{ 'is-stacked': stacked }">
                        <div
                            v-for="b in bars(ci)"
                            :key="b.name"
                            class="fu-bars__bar"
                            :class="{ 'is-dim': active && active !== `${c}|${b.name}` }"
                            :style="{ height: pctOf(b.value), background: b.color }"
                            :title="`${c} · ${b.name}: ${fmt(b.value)}`"
                            tabindex="0"
                            @mouseenter="active = `${c}|${b.name}`"
                            @mouseleave="active = null"
                            @click="emit('select', { category: c, series: b.name, value: b.value })"
                        >
                            <span v-if="showValues && b.value && !stacked" class="fu-bars__val">{{ fmt(b.value) }}</span>
                        </div>
                    </div>
                </div>
                <div class="fu-bars__xaxis">
                    <span v-for="c in categories" :key="c">{{ c }}</span>
                </div>
            </div>
        </div>

        <!-- HORIZONTAL -->
        <div v-else class="fu-bars__h">
            <div v-for="(c, ci) in categories" :key="c" class="fu-bars__hrow">
                <span class="fu-bars__hlabel">{{ c }}</span>
                <div class="fu-bars__htrack">
                    <div class="fu-bars__hgroup" :class="{ 'is-stacked': stacked }">
                        <div
                            v-for="b in bars(ci)"
                            :key="b.name"
                            class="fu-bars__hbar"
                            :class="{ 'is-dim': active && active !== `${c}|${b.name}` }"
                            :style="{ width: pctOf(b.value), background: b.color }"
                            :title="`${c} · ${b.name}: ${fmt(b.value)}`"
                            tabindex="0"
                            @mouseenter="active = `${c}|${b.name}`"
                            @mouseleave="active = null"
                            @click="emit('select', { category: c, series: b.name, value: b.value })"
                        />
                    </div>
                </div>
                <span v-if="showValues" class="fu-bars__hval">{{
                    fmt(stacked ? bars(ci).reduce((a, b) => a + b.value, 0) : Math.max(...bars(ci).map((b) => b.value)))
                }}</span>
            </div>
        </div>

        <figcaption v-if="legend && series.length > 1 && hasData && !loading" class="fu-bars__legend">
            <span v-for="s in coloured" :key="s.name"><i :style="{ background: s.color }" />{{ s.name }}</span>
        </figcaption>
    </figure>
</template>

