<script setup lang="ts">
/**
 * FusionProgressBar
 * A plain bar for progress, budget and retainer use. Can turn amber and red as it fills,
 * or split into segments (done, in progress, to do).
 */
import { computed } from "vue";

export interface ProgressSegment {
    value: number;
    label?: string;
    tone?: "default" | "success" | "info" | "warning" | "danger" | "muted";
    /** Any CSS colour. Wins over tone. */
    color?: string;
}

const props = withDefaults(
    defineProps<{
        /** Current amount. Use with `max`. */
        value?: number;
        max?: number;
        /** Several parts of one whole instead of a single value. */
        segments?: ProgressSegment[];
        label?: string;
        /** Text on the right, for example "14.5 of 20 h". Defaults to the percentage. */
        valueText?: string;
        showValue?: boolean;
        size?: "sm" | "md" | "lg";
        /** default: one colour. auto: grows amber at warnAt and red at dangerAt. */
        tone?: "default" | "success" | "warning" | "danger" | "auto";
        warnAt?: number;
        dangerAt?: number;
        /** Show a legend under a segmented bar. */
        legend?: boolean;
        indeterminate?: boolean;
    }>(),
    {
        value: 0,
        max: 100,
        showValue: true,
        size: "md",
        tone: "default",
        warnAt: 80,
        dangerAt: 100,
        legend: true,
    },
);

const pct = computed(() => {
    const total = props.segments?.length ? props.segments.reduce((a, s) => a + s.value, 0) : props.max;
    const v = props.segments?.length ? total : props.value;
    return total > 0 ? Math.min(100, Math.max(0, (v / props.max) * 100)) : 0;
});

const autoTone = computed(() => {
    if (props.tone !== "auto") return props.tone;
    const raw = props.max > 0 ? (props.value / props.max) * 100 : 0;
    return raw >= props.dangerAt ? "danger" : raw >= props.warnAt ? "warning" : "default";
});

const text = computed(() => props.valueText ?? `${Math.round(pct.value)}%`);

const parts = computed(() => {
    const segs = props.segments ?? [];
    const total = segs.reduce((a, s) => a + s.value, 0) || 1;
    return segs.map((s) => ({ ...s, width: `${(s.value / total) * 100}%` }));
});
</script>

<template>
    <div class="fu-progress" :class="[`fu-progress--${size}`]">
        <div v-if="label || showValue" class="fu-progress__head">
            <span class="fu-progress__label">{{ label }}</span>
            <span v-if="showValue && !indeterminate && !segments?.length" class="fu-progress__value">{{ text }}</span>
        </div>

        <div
            class="fu-progress__track"
            role="progressbar"
            :aria-valuenow="indeterminate ? undefined : Math.round(pct)"
            aria-valuemin="0"
            aria-valuemax="100"
            :aria-label="label || 'Progress'"
        >
            <template v-if="segments?.length">
                <span
                    v-for="p in parts"
                    :key="p.label || p.value"
                    class="fu-progress__seg"
                    :class="`is-${p.tone || 'default'}`"
                    :style="{ width: p.width, background: p.color }"
                    :title="p.label ? `${p.label}: ${p.value}` : undefined"
                />
            </template>
            <span
                v-else
                class="fu-progress__fill"
                :class="[`is-${autoTone}`, { 'is-indeterminate': indeterminate }]"
                :style="indeterminate ? undefined : { width: `${pct}%` }"
            />
        </div>

        <ul v-if="segments?.length && legend" class="fu-progress__legend">
            <li v-for="p in parts" :key="p.label || p.value">
                <span class="fu-progress__dot" :class="`is-${p.tone || 'default'}`" :style="{ background: p.color }" />
                {{ p.label }} <b>{{ p.value }}</b>
            </li>
        </ul>
    </div>
</template>

