<script setup lang="ts">
/**
 * FusionSelectionBar
 * The floating bar that appears once something is selected: how many, and what you can do with them.
 */
import { computed, type Component } from "vue";
import { X } from "@lucide/vue";
import FusionButton from "../button/FusionButton.vue";

export interface SelectionBarAction {
    /** Sent back in `action`. */
    key: string;
    label: string;
    icon?: Component;
    /** "primary" is the main action (green), "danger" is destructive (red). */
    tone?: "default" | "primary" | "danger";
    disabled?: boolean;
    loading?: boolean;
}

const props = withDefaults(
    defineProps<{
        /** How many things are selected. The bar hides itself at 0. */
        count: number;
        /** Word after the number, for example "selected" or "tasks selected". */
        label?: string;
        actions?: SelectionBarAction[];
        /** Show the x that clears the selection. */
        clearable?: boolean;
        clearLabel?: string;
        /** fixed: pinned to the bottom of the screen. sticky: sticks to the bottom of its scrolling parent. inline: sits where you place it. */
        position?: "fixed" | "sticky" | "inline";
        /** Force it shown or hidden. By default it shows when count is above 0. */
        visible?: boolean;
    }>(),
    {
        label: "selected",
        actions: () => [],
        clearable: true,
        clearLabel: "Clear selection",
        position: "fixed",
        visible: undefined,
    },
);

const emit = defineEmits<{
    (e: "action", key: string): void;
    (e: "clear"): void;
}>();

const shown = computed(() => (props.visible === undefined ? props.count > 0 : props.visible));

function variantOf(a: SelectionBarAction) {
    return a.tone === "danger" ? "danger" : a.tone === "primary" ? "success" : "ghost";
}
</script>

<template>
    <Transition name="fu-selbar">
        <div v-if="shown" class="fu-selbar" :class="`fu-selbar--${position}`" role="toolbar" aria-label="Selection actions">
            <div class="fu-selbar__count" aria-live="polite">
                <span class="fu-selbar__num">{{ count }}</span>
                <span>{{ label }}</span>
            </div>

            <div v-if="actions.length" class="fu-selbar__actions">
                <FusionButton
                    v-for="a in actions"
                    :key="a.key"
                    :text="a.label"
                    :icon="a.icon"
                    :variant="variantOf(a)"
                    :disabled="a.disabled"
                    :loading="a.loading"
                    size="sm"
                    :class="{ 'fu-selbar__btn': a.tone !== 'primary' && a.tone !== 'danger' }"
                    @click="emit('action', a.key)"
                />
            </div>

            <slot />

            <button v-if="clearable" type="button" class="fu-selbar__clear" :aria-label="clearLabel" @click="emit('clear')">
                <X :size="16" />
            </button>
        </div>
    </Transition>
</template>

